package limiter

import (
	"sync"
	"time"
)

// Limiter is a token bucket rate limiter.
type Limiter struct {
	rate     float64   // tokens per second
	burst    int       // maximum token capacity
	tokens   float64   // current token count
	last     time.Time // last refill time
	mu       sync.Mutex
}

// New creates a Limiter with given rate (tokens/sec) and burst capacity.
func New(rate float64, burst int) *Limiter {
	return &Limiter{
		rate:   rate,
		burst:  burst,
		tokens: float64(burst),
		last:   time.Now(),
	}
}

// Allow returns true if a request is allowed (consumes one token).
func (l *Limiter) Allow() bool {
	// TODO: implement token bucket Allow
	return false
}

// Tokens returns the current token count (for testing).
func (l *Limiter) Tokens() float64 {
	l.mu.Lock()
	defer l.mu.Unlock()
	return l.tokens
}

