package limiter_test

import (
	"sync"
	"testing"
	"time"

	"github.com/ai-verification/rate-limiter/limiter"
)

func TestAllowWithinBurst(t *testing.T) {
	l := limiter.New(10, 5)
	for i := 0; i < 5; i++ {
		if !l.Allow() {
			t.Fatalf("expected allow on request %d", i+1)
		}
	}
}

func TestDeniedWhenExhausted(t *testing.T) {
	l := limiter.New(10, 3)
	l.Allow(); l.Allow(); l.Allow()
	if l.Allow() {
		t.Fatal("expected deny after burst exhausted")
	}
}

func TestRefillOverTime(t *testing.T) {
	l := limiter.New(100, 1) // 100 tokens/sec, burst 1
	l.Allow() // exhaust
	time.Sleep(15 * time.Millisecond) // ~1.5 tokens should refill
	if !l.Allow() {
		t.Fatal("expected allow after refill")
	}
}

func TestBurstCapacity(t *testing.T) {
	l := limiter.New(100, 3)
	// Wait a long time — tokens should not exceed burst
	time.Sleep(200 * time.Millisecond)
	if l.Tokens() > 3 {
		t.Fatalf("tokens %f exceeded burst 3", l.Tokens())
	}
}

func TestConcurrentSafe(t *testing.T) {
	l := limiter.New(1000, 100)
	var wg sync.WaitGroup
	allowed := make(chan bool, 200)
	for i := 0; i < 200; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			allowed <- l.Allow()
		}()
	}
	wg.Wait()
	close(allowed)
	count := 0
	for a := range allowed {
		if a {
			count++
		}
	}
	if count > 100 {
		t.Fatalf("allowed %d but burst is 100", count)
	}
}
